using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" }
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, Code = "CS101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, data structures, and object-oriented design.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
            InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming pedagogy.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS301", Title = "Data Structures and Algorithms",
            Description = "Advanced study of data structures including trees, graphs, and hash tables. Covers algorithm analysis and design patterns.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM",
            InstructorName = "Dr. Bob Martinez",
            InstructorBio = "Dr. Martinez specializes in algorithm optimization and competitive programming. Former ACM ICPC coach.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 3, Code = "MATH201", Title = "Linear Algebra",
            Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to science and engineering.",
            Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM",
            InstructorName = "Dr. Sarah Kim",
            InstructorBio = "Dr. Kim is a researcher in applied mathematics with a focus on numerical methods and scientific computing.",
            DepartmentCode = "MATH", IsFeatured = true
        },
        new()
        {
            Id = 4, Code = "MATH101", Title = "Calculus I",
            Description = "Limits, derivatives, integrals, and their applications. Covers single-variable calculus with emphasis on problem solving.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM",
            InstructorName = "Dr. James Wilson",
            InstructorBio = "Dr. Wilson has taught calculus for over 20 years and authored two widely-used textbooks.",
            DepartmentCode = "MATH", IsFeatured = false
        },
        new()
        {
            Id = 5, Code = "ENG102", Title = "Academic Writing",
            Description = "Develop skills in argumentative and research-based writing. Covers thesis construction, evidence analysis, and citation practices.",
            Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM",
            InstructorName = "Prof. Diana Ross",
            InstructorBio = "Prof. Ross is a published author and writing workshop facilitator with expertise in rhetoric and composition.",
            DepartmentCode = "ENG", IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "PHYS201", Title = "Classical Mechanics",
            Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, central forces, and rigid body dynamics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 2:00–2:50 PM",
            InstructorName = "Dr. Richard Feynman Jr.",
            InstructorBio = "Dr. Feynman Jr. is an experimental physicist who brings real-world lab examples into the classroom.",
            DepartmentCode = "PHYS", IsFeatured = true
        },
        new()
        {
            Id = 7, Code = "HIST110", Title = "World History to 1500",
            Description = "Survey of major civilizations, cultural exchanges, and historical developments from antiquity through the late medieval period.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM",
            InstructorName = "Dr. Maria Gonzalez",
            InstructorBio = "Dr. Gonzalez is a historian specializing in cross-cultural exchanges along ancient trade routes.",
            DepartmentCode = "HIST", IsFeatured = false
        },
        new()
        {
            Id = 8, Code = "CS401", Title = "Machine Learning",
            Description = "Introduction to supervised and unsupervised learning, neural networks, decision trees, and model evaluation techniques.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM",
            InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming pedagogy.",
            DepartmentCode = "CS", IsFeatured = false
        }
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? query, string? departmentCode)
    {
        var results = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            results = results.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(query))
        {
            results = results.Where(c =>
                c.Title.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(query, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public Course? GetCourseByCode(string code) =>
        _courses.FirstOrDefault(c => c.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));
}

