@page "/courses"
@using UniversityCourseCatalog.Services
@using Microsoft.AspNetCore.Components
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Course title, code, or instructor" />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select id="department" name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Code" selected="@(dept.Code == Department)">@dept.Code — @dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, Department);
}

@if (courses.Count == 0)
{
    <p class="text-muted">No courses match your criteria.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentCode</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td><a href="/courses/@course.Code" class="btn btn-outline-primary btn-sm">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Department { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@Model.CourseCode</strong> has been received. You will be notified once it is processed.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <EditForm Model="Model" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit" class="row g-3" style="max-width: 600px;">
        <AntiforgeryToken />
        <DataAnnotationsValidator />

        <div class="col-12">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="col-12">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="col-12">
            <label for="courseCode" class="form-label">Course</label>
            <InputSelect id="courseCode" @bind-Value="Model.CourseCode" class="form-select">
                <option value="">— Select a course —</option>
                @foreach (var course in Catalog.GetAllCourses())
                {
                    <option value="@course.Code">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseCode" />
        </div>

        <div class="col-12">
            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </div>

        <ValidationSummary />
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? Course { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (!string.IsNullOrEmpty(Course) && string.IsNullOrEmpty(Model.CourseCode))
        {
            Model.CourseCode = Course;
        }
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}

